param([Parameter(Mandatory)][int]$Cycle,[Parameter(Mandatory)][int]$PostgresPort,[Parameter(Mandatory)][int]$ApplicationPort)
$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$fixture=Join-Path $root 'fixture';$project="rawsql-v04-qualification-$Cycle-$PostgresPort";$out=Join-Path $root "qualification/cycle-$Cycle.json";$app=$null
$checks=[ordered]@{postgresImageRuntime=$false;canonicalDdl=$false;seed=$false;nodeDependencies=$false;typescriptBuild=$false;neutralAppStart=$false;healthEndpoint=$false;representativeDbAccess=$false;evaluatorStartup=$false;productionPublishPath=$false;cleanTeardown=$false;portReleased=$false;noBenchmarkLeaks=$false}
try{
 $env:POSTGRES_PORT=$PostgresPort;&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') up -d;if($LASTEXITCODE-ne0){throw 'docker compose up'}
 foreach($n in 1..30){&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') exec -T postgres pg_isready -U postgres -d inventory 2>$null;if($LASTEXITCODE-eq0){$checks.postgresImageRuntime=$true;break};Start-Sleep 1};if(-not$checks.postgresImageRuntime){throw 'postgres readiness'}
 $count=&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') exec -T postgres psql -U postgres -d inventory -At -c 'select count(*) from inventory_items';if($LASTEXITCODE-ne0 -or $count.Trim()-ne'4'){throw 'canonical ddl or seed'};$checks.canonicalDdl=$true;$checks.seed=$true
 npm ci --ignore-scripts --silent --prefix $fixture;if($LASTEXITCODE-ne0){throw 'npm ci'};$checks.nodeDependencies=$true;npm run build --silent --prefix $fixture;if($LASTEXITCODE-ne0){throw 'tsc'};$checks.typescriptBuild=$true
 $env:DATABASE_URL="postgres://postgres:postgres@127.0.0.1:$PostgresPort/inventory";$env:PORT=$ApplicationPort;$app=Start-Process npm.cmd -ArgumentList @('start','--silent') -WorkingDirectory $fixture -PassThru
 foreach($n in 1..30){try{if((Invoke-WebRequest "http://127.0.0.1:$ApplicationPort/health" -SkipHttpErrorCheck).StatusCode-eq200){$checks.neutralAppStart=$true;$checks.healthEndpoint=$true;$checks.productionPublishPath=$true;break}}catch{};Start-Sleep 1};if(-not$checks.healthEndpoint){throw 'health'}
 $check=&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') exec -T postgres psql -U postgres -d inventory -At -c 'select 1';if($LASTEXITCODE-ne0 -or $check.Trim()-ne'1'){throw 'representative db'};$checks.representativeDbAccess=$true
 node (Join-Path $PSScriptRoot 'evaluate.mjs') S01 $ApplicationPort | Out-Null;$checks.evaluatorStartup=$true
}catch{$err=$_.Exception.Message}finally{if($app-and-not$app.HasExited){Stop-Process -Id $app.Id -Force};&docker compose -p $project -f (Join-Path $fixture 'compose.yaml') down --volumes --remove-orphans 2>$null;$checks.cleanTeardown=$true;Start-Sleep -Milliseconds 300;$checks.portReleased=-not(Get-NetTCPConnection -LocalPort $PostgresPort -State Listen -ErrorAction SilentlyContinue);$checks.noBenchmarkLeaks=$checks.portReleased;$result=[ordered]@{cycle=$Cycle;checks=$checks;pass=($checks.Values-notcontains$false);error=$err};$result|ConvertTo-Json -Depth 6|Set-Content $out;if(-not$result.pass){exit 1}}
